effect.shader:

vec2 encodeFloat(float v) {
    highp vec2 enc = fract(vec2(1.0, 255.0)*v);
    enc.x -= enc.y/255.0;
    return enc;
}

float decodeFloat(vec2 v) {
    return dot(v,vec2(1.0,1.0/255.0));
}

vec2 l2s( vec2 v ) {
    return (vec4(v,0.,1.)*acLayerToScreen).xy;
}


const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);

void main() {

    vec4 baseImg = texture2DCv(inputImg.texture, acScreenNorm);
    if(baseImg.a <= 0.0) {
        gl_FragColor = texture2DCv(comp.texture, acScreenNorm);
        return;
    }

    vec2 st = acLayerNorm;
    vec2 center = vec2(0.5, 0.5);
    vec2 dt = center - st;
    float count = length(dt) / 0.001;
    float accumScale = 0.0;
    for(float i = 0.0; i <= count; i += 1.0) {
        vec2 uv = st + dt * i / count;
        vec4 sample = texture2DCv(inputImg.texture, l2s(uv));
        float luminance = dot(sample.rgb, luminanceWeighting);
        float scale = ((1.0 -luminance) / 0.5);
        accumScale += scale;
    }
    vec2 scaledUV = center - dt / count * accumScale / baseScale;
    gl_FragColor = texture2DCv(comp.texture, l2s(scaledUV));
}
